    IChromaticEffect preset() {
        return EffectOptions.palette(0xFF6000, 0xFFFF00).option("amplitudeY", 2.5).create("wave", 1, 1, 0.5f);
    }
    // Common teardown. Retained old layouts stop invoking unloaded script effects.
    void close() { if (owned != null) owned.close(); }
}

